 window.addEventListener('beforeunload',e=>{if(attempt&&!receipt){e.preventDefault();e.returnValue='';}});
 controls();return {refresh,setExternalBusy(value){external=!!value;controls();},deny(){withdraw('Hay que verificar de nuevo tu acceso a Novedades.');},hasPending(){return !!attempt&&!receipt;}};
